package com.example.job_service.controller;

import com.example.job_service.common.ApiResponse;import com.example.job_service.dto.JobDtos;import com.example.job_service.entity.JobStatus;import com.example.job_service.exception.*;import com.example.job_service.security.RequestIdentity;import com.example.job_service.service.JobService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/employer/jobs") public class EmployerJobController {private final JobService jobs;public EmployerJobController(JobService jobs){this.jobs=jobs;}@GetMapping public ApiResponse<JobDtos.PageData<JobDtos.View>> list(@RequestParam UUID companyId,@RequestParam(required=false)JobStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,RequestIdentity identity,HttpServletRequest request){if(!"EMPLOYER".equals(identity.role()))throw new ApiException(HttpStatus.FORBIDDEN,"FORBIDDEN","Employer role is required");if(page<0||size<1||size>100)throw new ApiException(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Invalid pagination");return ApiResponse.ok("Company jobs retrieved",jobs.employerJobs(companyId,status,page,size,identity.userId(),String.valueOf(request.getAttribute(CorrelationIdFilter.ATTRIBUTE))));}}
